mapper.select:
SELECT id, request_digest AS requestDigest, record_id AS recordId
FROM ai_capability_form_receipt
WHERE tenant_id = #{tenantId} AND client_id = #{clientId}
  AND capability_id = #{capabilityId} AND key_hash = #{keyHash}
FOR UPDATE

mapper.update:
